usage:
package main

import (
	"bytes"
	"context"
	"fmt"
	"io"

	"github.com/example/openai"
	"github.com/example/openai/option"
)

func main() {
	client := openai.NewClient(
		option.WithAPIKey("My API Key"),
	)
	result, err := client.Uploads.Parts.New(
		context.TODO(),
		"upload_abc123",
		openai.UploadPartNewParams{
			Data: io.Reader(bytes.NewBuffer([]byte("Example data"))),
		},
	)
	if err != nil {
		panic(err.Error())
	}
	fmt.Printf("%+v\n", result)
}
